"""xWin model for Dota Pro Savant.

For each player in each match we build two groups of features:

EARLY (lane, measured at 10:00, before the game snowballs) - relative to the opposing player in the same position:
  e_gold  net-worth gold difference at 10:00 (hundreds)
  e_xp    XP difference at 10:00 (hundreds)
  e_lh    last-hit difference at 10:00
  e_dn    own denies at 10:00

CONTRIBUTION (whole game, as a share of the player's own team so a team-wide win doesn't inflate them):
  s_gold   share of team gold per minute
  s_dmg    share of team hero damage
  s_tower  share of team tower damage
  s_heal   share of team hero healing
  kp       kill participation: (kills + assists) / team kills
  s_death  share of team deaths (higher is worse)
  stun_m   stun seconds per minute
  ward_m   wards placed per 10 minutes
  stack_m  camps stacked per 10 minutes

Before fitting, the lane stats are measured against the hero's usual lane and every stat is adjusted for the
opponent's strength (see adjust_features).

One logistic regression per position predicts "did this player's team win?". xWin for a match is that predicted
probability; a player's xWin% is the average over their matches, and Wins Above Average (WAA), computed on the
dashboard, is the sum of (xWin - the position's average xWin) over their matches.
"""
import numpy as np
from scipy.optimize import minimize
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline

EARLY = ["e_gold", "e_xp", "e_lh", "e_dn"]
CONTRIB = ["s_gold", "s_dmg", "s_tower", "s_heal", "kp", "s_death", "stun_m", "ward_m", "stack_m"]
FEATURES = EARLY + CONTRIB
LABELS = {
    "e_gold": "Gold lead at 10:00", "e_xp": "XP lead at 10:00", "e_lh": "Last-hit lead at 10:00", "e_dn": "Denies at 10:00",
    "s_gold": "Share of team gold", "s_dmg": "Share of team hero damage", "s_tower": "Share of team tower damage",
    "s_heal": "Share of team healing", "kp": "Kill participation", "s_death": "Share of team deaths",
    "stun_m": "Stuns per minute", "ward_m": "Wards per 10 min", "stack_m": "Stacks per 10 min",
}


def _v(x):
    return 0.0 if x is None else float(x)


def build_features(pm, M):
    """Adds r['feat'] (dict) and r['win'] to every row of pm that has a position. Rows missing 10:00 data get None."""
    sides = {}
    for r in pm:
        sides.setdefault((r["match_id"], r["player_slot"] < 128), []).append(r)
    for (mid, radiant), team in sides.items():
        opp = sides.get((mid, not radiant), [])
        opp_by_pos = {o.get("pos"): o for o in opp}
        m = M[mid]
        mins = max((m["duration"] or 60) / 60, 1)
        tot = lambda k: sum(_v(t[k]) for t in team)
        t_gpm, t_dmg, t_tow, t_heal = tot("gold_per_min"), tot("hero_damage"), tot("tower_damage"), tot("hero_healing")
        t_k, t_d = tot("kills"), tot("deaths")
        for r in team:
            r["win"] = int(radiant == m["radiant_win"])
            o = opp_by_pos.get(r.get("pos"))
            if "pos" not in r or o is None or None in (r["g10"], r["x10"], r["l10"], o["g10"], o["x10"], o["l10"]):
                r["feat"] = None
                continue
            r["feat"] = {
                "e_gold": (r["g10"] - o["g10"]) / 100, "e_xp": (r["x10"] - o["x10"]) / 100,
                "e_lh": r["l10"] - o["l10"], "e_dn": _v(r["d10"]),
                "s_gold": _v(r["gold_per_min"]) / t_gpm if t_gpm else 0.2,
                "s_dmg": _v(r["hero_damage"]) / t_dmg if t_dmg else 0.2,
                "s_tower": _v(r["tower_damage"]) / t_tow if t_tow else 0.2,
                "s_heal": _v(r["hero_healing"]) / t_heal if t_heal else 0.0,
                "kp": (_v(r["kills"]) + _v(r["assists"])) / t_k if t_k else 0.0,
                "s_death": _v(r["deaths"]) / t_d if t_d else 0.2,
                "stun_m": _v(r["stuns"]) / mins, "ward_m": (_v(r["obs_placed"]) + _v(r["sen_placed"])) / mins * 10,
                "stack_m": _v(r["camps_stacked"]) / mins * 10,
            }


# Direction each stat is allowed to push xWin: +1 = more is better, -1 = more is worse.
# Fitting with these signs stops the model from rewarding a player for what their teammates did
# (e.g. a support "earning" xWin by dying more because the cores are thriving).
SIGN = {"e_gold": 1, "e_xp": 1, "e_lh": 1, "e_dn": 1, "s_gold": 1, "s_dmg": 1, "s_tower": 1, "s_heal": 1,
        "kp": 1, "s_death": -1, "stun_m": 1, "ward_m": 1, "stack_m": 1}


class SignedLogit(BaseEstimator, ClassifierMixin):
    """Logistic regression on standardized features whose coefficients are forced to the sign in `signs`."""

    def __init__(self, signs=None, l2=1e-4):
        self.signs = signs
        self.l2 = l2

    def fit(self, X, y):
        s = np.ones(X.shape[1]) if self.signs is None else np.asarray(self.signs, float)
        Z = X * s
        n, k = Z.shape

        def loss(w):
            z = Z @ w[1:] + w[0]
            p = 1 / (1 + np.exp(-z))
            ll = np.sum(np.logaddexp(0, z) - y * z) / n + self.l2 * np.sum(w[1:] ** 2)
            g = np.concatenate([[np.sum(p - y) / n], Z.T @ (p - y) / n + 2 * self.l2 * w[1:]])
            return ll, g

        res = minimize(loss, np.zeros(k + 1), jac=True, method="L-BFGS-B", bounds=[(None, None)] + [(0, None)] * k)
        self.intercept_ = res.x[0]
        self.coef_ = np.array([res.x[1:] * s])
        self.classes_ = np.array([0, 1])
        return self

    def predict_proba(self, X):
        p = 1 / (1 + np.exp(-(X @ self.coef_[0] + self.intercept_)))
        return np.column_stack([1 - p, p])


def make_model(feats=None, signed=True):
    if not signed:
        return make_pipeline(StandardScaler(), LogisticRegression(C=1.0, max_iter=2000))
    feats = feats or FEATURES
    return make_pipeline(StandardScaler(), SignedLogit(signs=[SIGN[f] for f in feats]))


HERO_PRIOR_GAMES = 20   # hero baselines are pulled toward 0 as if each hero had this many extra average games


def adjust_features(rows):
    """Adjusts each row's features in place (the originals are kept in r['feat_raw']).

    1. Hero: the four 10:00 lane stats are measured against what that hero usually does in that position.
       A roaming support or a hero that always loses lane is not marked down for it.
       Baseline = average over all games of the hero in the position, shrunk toward 0 by HERO_PRIOR_GAMES.
    2. Opponent: every stat is adjusted for how strong the opposing team was (their Elo going into the game).
       Per position, each stat is regressed on the opponent's Elo; the slope times (opp Elo - 1500) is removed,
       so a gold lead against a strong team counts for more than the same lead against a weak one.
    Returns the per-position slopes so they can be reported.
    """
    rs = [r for r in rows if r.get("feat") is not None]
    for r in rs:
        r["feat_raw"] = dict(r["feat"])
    sums = {}
    for r in rs:
        k = (r["pos"], r["hero_id"])
        s = sums.setdefault(k, {f: 0.0 for f in EARLY} | {"n": 0})
        s["n"] += 1
        for f in EARLY:
            s[f] += r["feat"][f]
    for r in rs:
        s = sums[(r["pos"], r["hero_id"])]
        for f in EARLY:
            r["feat"][f] -= s[f] / (s["n"] + HERO_PRIOR_GAMES)
    slopes = {}
    for pos in range(1, 6):
        g = [r for r in rs if r["pos"] == pos and r.get("opp_elo") is not None]
        if len(g) < 50:
            continue
        x = np.array([(r["opp_elo"] - 1500) / 100 for r in g])
        xc = x - x.mean()
        slopes[pos] = {}
        for f in FEATURES:
            y = np.array([r["feat"][f] for r in g])
            b = float((xc * (y - y.mean())).sum() / max((xc ** 2).sum(), 1e-9))
            slopes[pos][f] = b
            for r, xi in zip(g, x):
                r["feat"][f] -= b * xi
    return slopes


def matrix(rows, feats):
    return np.array([[r["feat"][f] for f in feats] for r in rows], dtype=float), np.array([r["win"] for r in rows])


def fit_all(rows, feats=FEATURES):
    """One model per position. Returns {pos: fitted pipeline}."""
    models = {}
    for pos in range(1, 6):
        rs = [r for r in rows if r.get("pos") == pos and r["feat"] is not None]
        X, y = matrix(rs, feats)
        models[pos] = make_model(feats).fit(X, y)
    return models


def predict(models, rows, feats=FEATURES):
    for pos, mdl in models.items():
        rs = [r for r in rows if r.get("pos") == pos and r["feat"] is not None]
        if not rs:
            continue
        X, _ = matrix(rs, feats)
        for r, p in zip(rs, mdl.predict_proba(X)[:, 1]):
            r["xwin"] = float(p)


PATCH_MIN_ROWS = 3000   # a patch gets its own model at a position only with at least this many player-games there


def fit_by_patch(rows, feats=FEATURES):
    """One model per (patch, position) where the patch has enough games; otherwise the all-patch model.
    Returns {"global": {pos: model}, "patch": {(patch, pos): model}}."""
    out = {"global": fit_all(rows, feats), "patch": {}}
    by = {}
    for r in rows:
        if r.get("feat") is not None:
            by.setdefault((r["patch"], r["pos"]), []).append(r)
    for (patch, pos), rs in by.items():
        if len(rs) >= PATCH_MIN_ROWS:
            X, y = matrix(rs, feats)
            out["patch"][(patch, pos)] = make_model(feats).fit(X, y)
    return out


def predict_by_patch(models, rows, feats=FEATURES):
    groups = {}
    for r in rows:
        if r.get("feat") is not None:
            groups.setdefault((r["patch"], r["pos"]), []).append(r)
    for (patch, pos), rs in groups.items():
        mdl = models["patch"].get((patch, pos)) or models["global"][pos]
        X, _ = matrix(rs, feats)
        for r, p in zip(rs, mdl.predict_proba(X)[:, 1]):
            r["xwin"] = float(p)


def weights(models, feats=FEATURES):
    """Standardized coefficients per position: how much one standard deviation of each stat moves the log-odds of winning."""
    out = {}
    for pos, mdl in models.items():
        coef = mdl[-1].coef_[0]
        out[pos] = {f: round(float(c), 3) for f, c in zip(feats, coef)}
    return out
